<?php require __DIR__.'/../bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['smtp_host','smtp_port','smtp_username','smtp_from_email','smtp_from_name'] as $k)set_setting($k,trim((string)post($k)));if(post('smtp_password')!==''&&!secret_is_masked_input((string)post('smtp_password')))set_secret_setting('smtp_password',trim((string)post('smtp_password')));flash('success','Email settings saved.');redirect('/admin/email.php');}$title='Email Settings';require __DIR__.'/../includes/header.php';?><div class="page-head"><h1>Email Configuration</h1></div><form class="card form-card" method="post"><?=csrf_field()?><div class="grid2"><label>SMTP Host<input name="smtp_host" value="<?=e(setting('smtp_host',''))?>"></label><label>Port<input name="smtp_port" value="<?=e(setting('smtp_port','587'))?>"></label><label>Username<input name="smtp_username" value="<?=e(setting('smtp_username',''))?>"></label><label>Password<div class="secret-control" data-secret-scope="system" data-secret-key="smtp_password"><input type="password" name="smtp_password" value="<?=secret_setting('smtp_password','')?'••••••••':''?>" data-secret-input data-masked="<?=secret_setting('smtp_password','')?1:0?>" placeholder="Enter to change"><button type="button" class="secret-action" data-secret-eye>👁</button><button type="button" class="secret-action" data-secret-copy>Copy</button></div></label><label>From Email<input name="smtp_from_email" value="<?=e(setting('smtp_from_email','support@pocketcat.online'))?>"></label><label>From Name<input name="smtp_from_name" value="<?=e(setting('smtp_from_name','PocketCat'))?>"></label></div><button class="btn">Save Settings</button></form><div class="card"><h2>Provider-managed mailbox features</h2><p>Mailbox creation, quota, forwarding, anti-spam and greylisting are controlled by the hosting provider unless its API is available. PocketCat does not fake control over provider infrastructure.</p></div><?php require __DIR__.'/../inclu